-- 3000 вымышленных участников. Ответы созданы программой и не оценены преподавателем.
-- Выполнять только в базе RemI_AI. Вся операция выполняется в одной транзакции.
-- Участники помечены набором attestation-3000-v1 и не являются реальными пользователями.
BEGIN;
DO $$ BEGIN
 IF current_database() <> 'RemI_AI' THEN RAISE EXCEPTION 'Выбрана не база RemI_AI'; END IF;
 IF EXISTS (SELECT 1 FROM pg_namespace WHERE nspname='attestation_demo_3000') THEN RAISE EXCEPTION 'Набор уже существует; повторная загрузка остановлена'; END IF;
 IF EXISTS (SELECT 1 FROM remi_project.students WHERE email LIKE 'attestation-3000-%@example.invalid') THEN RAISE EXCEPTION 'Адреса набора уже заняты'; END IF;
 IF (SELECT COUNT(*) FROM remi_project.competencies c JOIN remi_project.topics t USING(topic_id) JOIN remi_project.disciplines d USING(discipline_id) WHERE c.name='Распознавать дифференциальное уравнение' AND d.name='Дифференциальные уравнения') <> 1 THEN RAISE EXCEPTION 'Не найдена однозначная компетенция'; END IF;
END $$;
CREATE SCHEMA attestation_demo_3000;
INSERT INTO remi_project.students(display_name,email)
SELECT 'Учебный участник аттестации '||lpad(n::text,4,'0'), 'attestation-3000-'||lpad(n::text,4,'0')||'@example.invalid' FROM generate_series(1,3000) AS n;
INSERT INTO remi_project.synthetic_students(student_id,dataset_name,student_number)
SELECT s.student_id,'attestation-3000-v1',n FROM generate_series(1,3000) AS n JOIN remi_project.students s ON s.email='attestation-3000-'||lpad(n::text,4,'0')||'@example.invalid';
INSERT INTO remi_project.diagnostic_sessions(student_id,target_competency_id,started_at,finished_at,status,stop_reason)
SELECT ss.student_id,c.competency_id, TIMESTAMP '2026-01-01 09:00' + ss.student_number * INTERVAL '1 minute', TIMESTAMP '2026-01-01 09:10' + ss.student_number * INTERVAL '1 minute', 'completed','Синтетическая учебная сессия attestation-3000-v1; оценки не подтверждены'
FROM remi_project.synthetic_students ss CROSS JOIN remi_project.competencies c JOIN remi_project.topics t USING(topic_id) JOIN remi_project.disciplines d USING(discipline_id)
WHERE ss.dataset_name='attestation-3000-v1' AND c.name='Распознавать дифференциальное уравнение' AND d.name='Дифференциальные уравнения';
CREATE TEMP TABLE staging_answers(student_number INTEGER,stage TEXT,topic TEXT,question_number INTEGER,correct INTEGER) ON COMMIT DROP;
