(3000,'followup','derivatives',3,1),
(3000,'initial','derivatives',1,1),
(3000,'initial','derivatives',2,1),
(3000,'initial','equations',1,1),
(3000,'initial','equations',2,1);
CREATE TABLE attestation_demo_3000.answers (
  session_id INTEGER NOT NULL REFERENCES remi_project.diagnostic_sessions(session_id),
  stage TEXT NOT NULL CHECK(stage IN ('initial','followup')),
  topic TEXT NOT NULL CHECK(topic IN ('equations','derivatives')),
  question_number INTEGER NOT NULL, correct INTEGER NOT NULL CHECK(correct IN (0,1)),
  grading_status TEXT NOT NULL DEFAULT 'synthetic_ungraded',
  PRIMARY KEY(session_id,stage,topic,question_number)
);
INSERT INTO attestation_demo_3000.answers(session_id,stage,topic,question_number,correct)
SELECT ds.session_id,a.stage,a.topic,a.question_number,a.correct FROM staging_answers a
JOIN remi_project.synthetic_students ss ON ss.dataset_name='attestation-3000-v1' AND ss.student_number=a.student_number
JOIN remi_project.diagnostic_sessions ds ON ds.student_id=ss.student_id AND ds.stop_reason='Синтетическая учебная сессия attestation-3000-v1; оценки не подтверждены';
CREATE VIEW attestation_demo_3000.diagnostic_features AS
SELECT ss.student_number AS session_id,
 SUM(CASE WHEN a.stage='initial' AND a.topic='equations' THEN 1 ELSE 0 END) AS initial_equations_count,
 SUM(CASE WHEN a.stage='initial' AND a.topic='equations' AND a.correct=1 THEN 1 ELSE 0 END) AS initial_equations_correct,
 SUM(CASE WHEN a.stage='initial' AND a.topic='derivatives' THEN 1 ELSE 0 END) AS initial_derivatives_count,
 SUM(CASE WHEN a.stage='initial' AND a.topic='derivatives' AND a.correct=1 THEN 1 ELSE 0 END) AS initial_derivatives_correct,
 SUM(CASE WHEN a.stage='followup' AND a.topic='derivatives' THEN 1 ELSE 0 END) AS followup_count,
 SUM(CASE WHEN a.stage='followup' AND a.topic='derivatives' AND a.correct=1 THEN 1 ELSE 0 END) AS followup_correct,
 CASE WHEN SUM(CASE WHEN a.stage='followup' AND a.topic='derivatives' THEN 1 ELSE 0 END)=3 THEN
   CASE WHEN SUM(CASE WHEN a.stage='followup' AND a.topic='derivatives' AND a.correct=1 THEN 1 ELSE 0 END)<=1 THEN 1 ELSE 0 END ELSE NULL END AS needs_review
FROM remi_project.synthetic_students ss
JOIN remi_project.diagnostic_sessions ds ON ds.student_id=ss.student_id AND ds.stop_reason='Синтетическая учебная сессия attestation-3000-v1; оценки не подтверждены'
JOIN attestation_demo_3000.answers a ON a.session_id=ds.session_id
WHERE ss.dataset_name='attestation-3000-v1' GROUP BY ss.student_number;
DO $$ BEGIN
 IF (SELECT COUNT(*) FROM remi_project.synthetic_students WHERE dataset_name='attestation-3000-v1')<>3000 OR
    (SELECT COUNT(*) FROM attestation_demo_3000.answers)<>21000 OR
    (SELECT COUNT(*) FROM attestation_demo_3000.diagnostic_features)<>3000 OR
    (SELECT COUNT(*) FROM attestation_demo_3000.diagnostic_features WHERE initial_equations_count<>2 OR initial_derivatives_count<>2 OR followup_count<>3 OR needs_review IS NULL)<>0
 THEN RAISE EXCEPTION 'Учебный набор неполный: изменения отменены'; END IF;
END $$;
COMMIT;
SELECT COUNT(*) AS sessions, SUM(needs_review) AS review_cases FROM attestation_demo_3000.diagnostic_features;
